import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, lineDiscount, lineVAT } from '../src/invoices.js';

test('createInvoice creates a draft invoice with product details', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  const inv = result.value;
  assert.equal(inv.customerId, 'C-001');
  assert.equal(inv.issueDate, '2026-10-07');
  assert.equal(inv.status, 'draft');
  assert.equal(inv.lines.length, 1);
  assert.equal(inv.lines[0].sku, 'DES-HOUR');
  assert.equal(inv.lines[0].name, 'Design work (hour)');
  assert.equal(inv.lines[0].qty, 5);
  assert.equal(inv.lines[0].unitPrice, 8500);
  assert.equal(inv.lines[0].vatRate, 21);
});

test('createInvoice normalizes customer ID', () => {
  const result = createInvoice({
    customerId: '  c-001  ',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice accepts lowercase customer ID', () => {
  const result = createInvoice({
    customerId: 'c-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
});

test('createInvoice defaults to NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts NET14 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET14');
  assert.equal(result.value.dueDate, '2026-10-21');
});

test('createInvoice accepts NET30 terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2026-11-06');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2026-10-31');
});

test('createInvoice rejects invalid terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET45',
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'TERMS_INVALID');
});

test('createInvoice EOM handles month boundaries', () => {
  // February 2024 (leap year) has 29 days
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result1.value.dueDate, '2024-02-29');

  // February 2025 (not leap year) has 28 days
  const result2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result2.value.dueDate, '2025-02-28');

  // December has 31 days
  const result3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });
  assert.equal(result3.value.dueDate, '2026-12-31');
});

test('createInvoice NET14 with month boundary', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-25',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET14',
  });
  assert.equal(result.value.dueDate, '2026-11-08');
});

test('createInvoice NET30 with year boundary', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });
  assert.equal(result.value.dueDate, '2027-01-14');
});

test('createInvoice supports multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-06',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[1].name, 'Logo package');
});

test('createInvoice reports unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026/10/07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects incomplete date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects invalid month', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-13-01',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects invalid day', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-02-30',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects zero day', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-00',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects non-string date', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: 20261007,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('createInvoice rejects empty lines array', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [],
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects non-array lines', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: null,
    }),
    { ok: false, error: 'NO_LINES' }
  );
});

test('createInvoice rejects zero quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 0 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects negative quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: -5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects fractional quantity', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 5.5 }],
    }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('createInvoice rejects unknown SKU', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
    }),
    { ok: false, error: 'UNKNOWN_SKU' }
  );
});

test('createInvoice stops at first error (customer before date)', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: 'invalid',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('createInvoice does not mutate input', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  };
  const original = JSON.stringify(input);
  createInvoice(input);
  assert.equal(JSON.stringify(input), original);
});

test('createInvoice accepts valid dates', () => {
  const validDates = [
    '2026-01-01', // Jan 1
    '2026-02-28', // Feb 28
    '2024-02-29', // leap year
    '2026-12-31', // Dec 31
  ];

  for (const date of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `Date ${date} should be valid`);
  }
});

test('createInvoice rejects non-leap-year Feb 29', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2025-02-29',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }),
    { ok: false, error: 'DATE_INVALID' }
  );
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal with qty of 1', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 5000 }), 5000);
});

test('lineTotal with large quantities', () => {
  assert.equal(lineTotal({ qty: 1000, unitPrice: 1000 }), 1000000);
});

test('invoiceTotals sums all line totals', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, vatRate: 0 },
      { qty: 10, unitPrice: 9500, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500 + 95000); // 137500
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 120000, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 120000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 120000);
});

test('invoiceTotals with multiple lines of varying amounts', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 1000, vatRate: 0 },
      { qty: 3, unitPrice: 5000, vatRate: 0 },
      { qty: 1, unitPrice: 10000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // 2*1000 + 3*5000 + 1*10000 = 2000 + 15000 + 10000 = 27000
  assert.equal(totals.subtotal, 27000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 27000);
});

test('invoiceTotals on a created invoice', () => {
  // C-002 is standard tier (0% discount)
  const result = createInvoice({
    customerId: 'C-002',
